// Server shape (GET /todos/:id)
interface TodoDto {
  id: number;
  title: string;
  due_date: string | null; // snake_case from the API
  priority: 1 | 2 | 3;
}

// Request shape (POST /todos): the server assigns id
type CreateTodoDto = Omit<TodoDto, "id">;

// Request shape (PATCH /todos/:id): any subset
type UpdateTodoDto = Partial<CreateTodoDto>;

// Form state: everything is a string
type TodoForm = { [K in keyof CreateTodoDto]: string };
